template<class T>
void BST<T>::iterativePostorder() { 
 Stack<BSTNode<T>*> travStack;
 BSTNode<T>* p = root, *q = root;
 while (p != 0) {
 for ( ; p->left != 0; p = p->left)
 travStack.push(p);
 while (p->right == 0 || p->right == q) {
 visit(p);
 q = p;
 if (travStack.empty())
 return;
 p = travStack.pop();
 }
 travStack.push(p);
 p = p->right;
 }
}
